<script setup>
import { ref, onMounted } from 'vue'
import { api } from '../../api/client'
import { workspace, money } from '../../services/workspace'
function date(delta) { const d = new Date(); d.setDate(d.getDate() + delta); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0') }
const from = ref(date(-6)), to = ref(date(1)), report = ref(null), error = ref(''), busy = ref(false)
async function load() { busy.value = true; error.value = ''; try { report.value = await api('/api/v1/reports/revenue?' + new URLSearchParams({ from: from.value, to: to.value, branch: workspace.branch })) } catch (e) { error.value = e.message } finally { busy.value = false } }
function csv() { if (!report.value) return; if (Date.now() > Date.parse(report.value.meta.validUntil)) { error.value = 'Snapshot quá 60 giây. Tải lại báo cáo trước khi xuất.'; return } const fields = ['day','orders','gross','discounts','sales','refunds','net','collected','receivable','cost','gross_profit']; const rows = [fields, ...report.value.daily.map(row => fields.map(key => row[key] ?? ''))]; const blob = new Blob(['\uFEFF' + rows.map(row => row.map(v => '"' + String(v).replaceAll('"','""') + '"').join(',')).join('\r\n')], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob), link = document.createElement('a'); link.href = url; link.download = 'PolyCafe-doanh-thu.csv'; link.click(); URL.revokeObjectURL(url) }
onMounted(load)
</script>
<template><h1>Báo cáo từ dữ liệu đã ghi</h1><p>Khoảng ngày gồm ngày bắt đầu và không gồm ngày kết thúc. Muốn xem hết hôm nay, chọn ngày kết thúc là ngày mai.</p><form class="toolbar" @submit.prevent="load"><label>Từ ngày<input v-model="from" type="date" required></label><label>Đến trước ngày<input v-model="to" type="date" required></label><button :disabled="busy">Tải báo cáo</button><button type="button" class="secondary" :disabled="!report || busy" @click="csv">Xuất CSV cùng snapshot</button></form><p v-if="error" role="alert" class="error">{{ error }}</p><template v-if="report"><p>Chốt dữ liệu lúc {{ new Date(report.meta.asOf).toLocaleString('vi-VN') }} · {{ report.meta.basis }}</p><p v-if="report.meta.warnings.length" class="notice">Cảnh báo: {{ report.meta.warnings.join(', ') }}. Giá vốn thiếu không được tự điền bằng 0.</p><div class="table-scroll"><table><thead><tr><th>Ngày kinh doanh</th><th>Đơn thu đủ</th><th>Trước giảm</th><th>Giảm giá</th><th>Sau giảm</th><th>Hoàn tiền</th><th>Thuần</th><th>Đã thu</th><th>Còn phải thu</th><th>Giá vốn</th><th>Lãi gộp</th></tr></thead><tbody><tr v-for="d in report.daily" :key="d.day"><td>{{ d.day }}</td><td>{{ d.orders }}</td><td>{{ money(d.gross) }}</td><td>{{ money(d.discounts) }}</td><td>{{ money(d.sales) }}</td><td>{{ money(d.refunds) }}</td><td>{{ money(d.net) }}</td><td>{{ money(d.collected) }}</td><td>{{ money(d.receivable) }}</td><td>{{ money(d.cost) }}</td><td>{{ money(d.gross_profit) }}</td></tr></tbody></table></div><section class="card"><h2>Thu và hoàn theo phương thức</h2><p v-for="c in report.collections" :key="c.method + c.kind">{{ c.method }} · {{ c.kind === 'collect' ? 'Thu' : 'Hoàn' }}: {{ money(c.amount) }}</p></section></template></template>
